INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','what''s for dinner','',NULL,'/wʌts fɔːr ˈdɪnər/','"What''s for dinner?" I asked Mom.','“晚饭吃什么?”我问妈妈。','What''s for dinner tonight — soup or noodles?','今晚吃什么——汤还是面?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','go shopping','',NULL,'/ɡoʊ ˈʃɑːpɪŋ/','Do we have to go shopping first?','我们得先去购物吗?','We go shopping every Saturday morning.','我们每周六上午去购物。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','be careful with','',NULL,'/bi ˈkerfl wɪð/','You must be careful with the knife.','用刀你必须小心。','Be careful with the hot pot.','小心那个热锅。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l90','cook together','',NULL,'/kʊk təˈɡeðər/','We must cook together more often.','我们真该多一起做饭。','The whole family likes to cook together.','全家人都喜欢一起做饭。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''You ___ wash your hands before you help,'' Mom said.\"(必须、务必)","options":["can","would","may","must"],"answer_index":3,"stem_cn":"“帮忙前你必须先洗手,”妈妈说。","explanation_cn":"主观上“必须、务必”,用 must + 动词原形。✓ You must wash your hands. ✗ can:能够;✗ may:也许/可以;✗ would:意愿,不表“必须”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''This soup ___ taste amazing — it smells great!'' my brother said.\"(对现在的肯定推测:一定)","options":["would","must","can","need"],"answer_index":1,"stem_cn":"“这汤闻着真香,一定特别好喝!”弟弟说。","explanation_cn":"对现在的肯定推测“一定”,用 must + 原形。✓ This soup must taste amazing. ✗ can:能够/也许;✗ need:此处不搭;✗ would:不表推测。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp1','choice','{"stem":"\"''You ___ be careful with the knife,'' Mom warned.\"(务必、一定要)","options":["must","would","could","might"],"answer_index":0,"stem_cn":"“用刀一定要小心,”妈妈提醒道。","explanation_cn":"“务必、一定要”,用 must。✓ You must be careful with the knife. ✗ could:能够/也许;✗ might:也许;✗ would:意愿。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"''Do we ___ go shopping first?'' I asked.\"(客观上是否必须)","options":["must to","must","have to","having to"],"answer_index":2,"stem_cn":"“我们得先去买东西吗?”我问。","explanation_cn":"客观上“必须”,用 have to + 原形。✓ Do we have to go shopping first? ✗ must:此处需与 Do 连用作疑问,应用 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"On busy days, Mom ___ cook for the whole family.\"(客观上必须)","options":["has to","are to","must to","have to"],"answer_index":0,"stem_cn":"忙的时候,妈妈得给全家做饭。","explanation_cn":"客观上“必须”,主语是 Mom(单数),用 has to。✓ Mom has to cook for the whole family. ✗ must to:must 后不加 to;✗ have to:主语单数应用 has to;✗ are to:表安排。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp2','choice','{"stem":"\"Yesterday we ___ buy more rice for dinner.\"(过去客观上不得不)","options":["has to","must","had to","will have to"],"answer_index":2,"stem_cn":"昨天我们不得不多买些米做晚饭。","explanation_cn":"过去客观上“不得不”,用 had to。✓ Yesterday we had to buy more rice. ✗ must:不表过去;✗ has to:一般现在;✗ will have to:将来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''No, we ___. We have everything we need,'' Mom said.\"(不必)","options":["needn''t","mustn''t","should","must"],"answer_index":0,"stem_cn":"“不用,该有的都有了,”妈妈说。","explanation_cn":"“不必、无需”,用 needn''t + 原形。✓ No, we needn''t. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''We ___ hurry — dinner isn''t until six-thirty,'' Mom said.\"(不必)","options":["have to","must not","don''t have to","need"],"answer_index":2,"stem_cn":"“我们不用赶——晚饭六点半才吃,”妈妈说。","explanation_cn":"“不必、没必要”,用 don''t have to。✓ We don''t have to hurry. ✗ must not:是“禁止”;✗ have to:是“必须”;✗ need:此处不搭。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp3','choice','{"stem":"\"''Dinner ___ be ready until six-thirty,'' she added.\"(不必、无需)","options":["has to","must","mustn''t","needn''t"],"answer_index":3,"stem_cn":"“晚饭不必六点半前做好,”她补充道。","explanation_cn":"“不必、无需”,用 needn''t。✓ Dinner needn''t be ready until six-thirty. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ has to:是“必须”。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''We ___ start cooking soon,'' Mom said.\"(应该、建议)","options":["need","should","must have","would"],"answer_index":1,"stem_cn":"“我们该动手做饭了,”妈妈说。","explanation_cn":"“应该、建议”,用 should + 原形。✓ We should start cooking soon. ✗ must have:对过去的推测;✗ need:不搭;✗ would:不表“应该”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''___ I chop the vegetables?'' I asked.\"(征求意见:该……吗)","options":["Should","Do","Must","Would"],"answer_index":0,"stem_cn":"“我来切菜吗?”我问。","explanation_cn":"征求意见“我该……吗”,用 Should 提到句首。✓ Should I chop the vegetables? ✗ Must:语气过强;✗ Do:与原形 chop 不搭作此意;✗ Would:委婉意愿,不表“该不该”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp4','choice','{"stem":"\"''You ___ try it when it''s done,'' Mom laughed.\"(应该、建议)","options":["must have","would have","need","should"],"answer_index":3,"stem_cn":"“做好了你尝尝,”妈妈笑道。","explanation_cn":"“应该、建议”,用 should。✓ You should try it when it''s done. ✗ must have:对过去的推测;✗ need:不搭;✗ would have:与过去相反的假设。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"''We ___ cook together more often — it''s fun!''\"(说话人自己强烈的感受、建议)","options":["have to","must","had to","are to"],"answer_index":1,"stem_cn":"“我们真该多一起做饭——太有意思了!”","explanation_cn":"说话人自己强烈的感受、建议,用 must。✓ We must cook together more often. ✗ have to:多表外在客观要求,这里是主观愿望;✗ had to:过去;✗ are to:表安排。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"The recipe says we ___ add salt, though I don''t think we need it.\"(菜谱这一外在要求)","options":["has to","are having to","must to","have to"],"answer_index":3,"stem_cn":"菜谱说要加盐,不过我觉得不用。","explanation_cn":"菜谱这一外在要求,用 have to。✓ The recipe says we have to add salt. ✗ must to:must 后不加 to;✗ has to:主语是 we,应用 have to;✗ are having to:形式不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp5','choice','{"stem":"\"''You ___ wash your hands — that''s the kitchen rule.''\"(外在客观的规定)","options":["has to","have to","must to","are to"],"answer_index":1,"stem_cn":"“你得洗手——这是厨房规矩。”","explanation_cn":"外在客观的规定,用 have to。✓ You have to wash your hands — that''s the kitchen rule. ✗ must to:must 后不加 to;✗ has to:主语是 you,应用 have to;✗ are to:表安排。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"Please ___ the vegetables into small pieces.\"(切、剁用哪个词)","options":["chop","sing","drink","sleep"],"answer_index":0,"stem_cn":"请把蔬菜切成小块。","explanation_cn":"“切、剁”是 chop。✓ chop the vegetables. ✗ drink:喝;✗ sleep:睡觉;✗ sing:唱歌。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"Be careful with the sharp ___.\"(刀用哪个词)","options":["plate","cup","spoon","knife"],"answer_index":3,"stem_cn":"小心那把锋利的刀。","explanation_cn":"“刀”是 knife。✓ be careful with the knife. ✗ spoon:勺子;✗ cup:杯子;✗ plate:盘子。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',5,'am2_l90_gp6','choice','{"stem":"\"This ___ smells great and tastes amazing.\"(汤用哪个词)","options":["soup","book","chair","shoe"],"answer_index":0,"stem_cn":"这汤闻着香、喝着也好。","explanation_cn":"“汤”是 soup。✓ This soup smells great. ✗ chair:椅子;✗ book:书;✗ shoe:鞋。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"美语里\"炉灶\"说:","options":["cooker","oven-box","stove","heater"],"answer_index":2,"explanation_cn":"美语“炉灶”说 stove;英式说 cooker。✓ She put the pot on the stove. 她把锅放在炉灶上。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"美语里\"水龙头\"说:","options":["spout","faucet","tap","valve"],"answer_index":1,"explanation_cn":"美语“水龙头”说 faucet;英式说 tap。✓ Turn off the faucet. 关掉水龙头。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"chop 的意思是:","options":["切,剁","洗","喝","烤"],"answer_index":0,"explanation_cn":"chop = 切、剁。✓ chop the vegetables 切菜。\n顺带记:喝 = drink;洗 = wash;烤 = bake."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"knife 的意思是:","options":["勺子","杯子","盘子","刀"],"answer_index":3,"explanation_cn":"knife = 刀。✓ careful with the knife 用刀小心。\n顺带记:勺子 = spoon;杯子 = cup;盘子 = plate."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"taste 的意思是:","options":["尝;有……的味道","看","闻","听"],"answer_index":0,"explanation_cn":"taste = 尝;有……的味道。✓ This soup must taste amazing 这汤一定很好喝。\n顺带记:闻 = smell;看 = look;听 = listen."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',6,NULL,'choice','{"stem":"remind 的意思是:","options":["表扬","责备","忘记","提醒"],"answer_index":3,"explanation_cn":"remind = 提醒。✓ Mom reminded me 妈妈提醒我。\n顺带记:忘记 = forget;责备 = blame;表扬 = praise."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 1 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":1,"options":["should","must have","need","would"],"answer_index":0,"explanation_cn":"“应该、建议”,用 should。✓ We should start cooking soon.\n✗ must have:对过去的推测;✗ need:不搭;✗ would:不表“应该”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 2 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":2,"options":["have to","must","must to","having to"],"answer_index":0,"explanation_cn":"客观上“必须”,用 have to。✓ Do we have to go shopping first?\n✗ must:此处作疑问需 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 3 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":3,"options":["needn''t","mustn''t","must","should"],"answer_index":0,"explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',7,NULL,'cloze','{"stem":"第 4 空","context":"\"We ___1___ start cooking soon,\" Mom said. \"Do we ___2___ go shopping first?\" I asked. \"No, we ___3___,\" she said. \"You ___4___ wash your hands before you help.\"","blank_no":4,"options":["must","can","may","would"],"answer_index":0,"explanation_cn":"主观上“必须、务必”,用 must。✓ You must wash your hands.\n✗ can:能够;✗ may:也许/可以;✗ would:意愿。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"When will Dad be home for dinner?","options":["At five","At six","At seven","At eight"],"answer_index":1,"explanation_cn":"课文说 \"Dad will be home at six.\""}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"Did they have to go shopping first?","options":["Yes, they were out of food","Yes, they needed rice","No, the store was closed","No, they had everything they needed"],"answer_index":3,"explanation_cn":"课文说 \"No, we needn''t. We have everything we need.\""}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',8,NULL,'choice','{"stem":"What must the child do before helping?","options":["Wash their hands","Set the table","Turn on the oven","Call Dad"],"answer_index":0,"explanation_cn":"课文说 \"You must wash your hands before you help.\""}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"我们得先去购物吗?\"(客观上是否必须,用 do...have to):","options":["Do we must go shopping first?","Have we to going shopping first?","Do we have to go shopping first?","Must we to go shopping first?"],"answer_index":2,"explanation_cn":"客观上是否必须,用 do...have to + 原形。✓ Do we have to go shopping first? 场合:问某件事是不是非做不可。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"不,我们不必。需要的都有了\"(不必,用 needn''t):","options":["No, we haven''t to. We have everything we need.","No, we don''t must. We have everything we need.","No, we mustn''t. We have everything we need.","No, we needn''t. We have everything we need."],"answer_index":3,"explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t. We have everything we need. 场合:回答“不必这么做”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',9,NULL,'choice','{"stem":"你想说\"帮忙前你必须洗手\"(必须,用 must):","options":["You should washed your hands before you help.","You must wash your hands before you help.","You have to washing your hands before you help.","You must to wash your hands before you help."],"answer_index":1,"explanation_cn":"主观上“必须、务必”,用 must + 原形。✓ You must wash your hands before you help. 场合:提出一个必须遵守的要求。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"chop 的意思是:","options":["切,剁","烤","洗","喝"],"answer_index":0,"explanation_cn":"chop = 切、剁。✓ chop the vegetables 切菜。\n顺带记:喝 = drink;洗 = wash;烤 = bake."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"soup 的意思是:","options":["鞋","汤","书","椅子"],"answer_index":1,"explanation_cn":"soup = 汤。✓ This soup smells great 这汤闻着真香。\n顺带记:椅子 = chair;书 = book;鞋 = shoe."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"''Do we ___ go shopping first?'' I asked.\"(客观上是否必须)","options":["have to","must to","having to","must"],"answer_index":0,"stem_cn":"“我们得先去买东西吗?”我问。","explanation_cn":"客观上“必须”,用 have to。✓ Do we have to go shopping first?\n✗ must:此处作疑问需 have to;✗ must to:must 后不加 to;✗ having to:形式不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"''No, we ___. We have everything we need.''\"(不必)","options":["must","needn''t","mustn''t","should"],"answer_index":1,"stem_cn":"“不用,该有的都有了。”","explanation_cn":"“不必、无需”,用 needn''t。✓ No, we needn''t.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"what''s for dinner\" 的意思是:","options":["谁做晚饭","晚饭之前","为了晚饭","晚饭吃什么"],"answer_index":3,"explanation_cn":"what''s for dinner = 晚饭吃什么。✓ \"What''s for dinner?\" I asked Mom。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"\"be careful with\" 的意思是:","options":["充满……","关心某人","小心对待、当心","忙于……"],"answer_index":2,"explanation_cn":"be careful with = 小心对待、当心。✓ You must be careful with the knife。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"What did Mom remind the child to do?","options":["Buy more rice","Wash their hands","Call Dad","Set the table"],"answer_index":1,"passage":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"You must wash your hands before you help.\""}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"When does dinner need to be ready?","options":["By five o''clock","Right away","By noon","By six-thirty"],"answer_index":3,"passage":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 dinner needn''t be ready until six-thirty——即六点半前好就行。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"When will Dad be home?","options":["At five","At seven","At six","At eight"],"answer_index":2,"audio":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"Dad will be home at six.\""}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l90',10,NULL,'choice','{"stem":"What must the child be careful with?","options":["The window","The knife","The phone","The door"],"answer_index":1,"audio":"\"We should start cooking soon,\" Mom said. \"Dad will be home at six.\" \"Do we have to go shopping first?\" I asked. \"No, we needn''t. We have everything we need.\" \"You must wash your hands before you help,\" Mom reminded me. \"Should I chop the vegetables?\" I asked. \"Yes, but you must be careful with the knife.\" \"We don''t have to hurry — dinner needn''t be ready until six-thirty.\" \"This soup must taste amazing,\" said my brother. \"It smells great!\" \"You should try it when it''s done,\" Mom laughed. \"We must cook together more often — it''s fun!\"","explanation_cn":"课文说 \"You must be careful with the knife.\""}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
